pub fn command(index: u32, speed: u32, accel: u32) -> Decision {
    if index >= MOTORS {
        Decision::NoMotor
    } else if speed == 0 || accel == 0 {
        Decision::BadMove
    } else {
        Decision::Queue { motor: index }
    }
}

